.steps {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  column-gap: var(--space-32);
}

.step {
  position: relative;
  padding-top: var(--space-24);
}

/* A short rule joins each picture to the next, level with the pictures' middles. */
.step + .step::before {
  position: absolute;
  top: calc(var(--space-24) + 6.25vw);
  left: calc(var(--space-32) * -1);
  width: var(--space-32);
  height: 1px;
  background: var(--color-placeholder);
  content: "";
}

.thumb {
  position: relative;
  aspect-ratio: 16 / 10;
}

.thumb > [role="img"] {
  position: absolute;
  inset: 0;
}

/* The flat glyph rides on the illustration, on a paper tab. */
.glyphTab {
  position: absolute;
  left: var(--space-8);
  bottom: var(--space-8);
  padding: 2px 4px 0;
  border-radius: 3px;
  background: rgb(255 255 255 / 92%);
  box-shadow: 0 6px 16px -8px rgb(0 0 0 / 50%);
}

.stepTitle {
  display: flex;
  gap: var(--space-8);
  align-items: baseline;
  margin-top: var(--space-16);
  font-size: var(--text-body);
  font-weight: var(--weight-semibold);
}

.stepNo {
  font-variant-numeric: tabular-nums;
  color: var(--color-grey-2);
}

.stepText {
  max-width: 30ch;
  margin-top: var(--space-4);
  font-size: var(--text-body-sm);
  color: var(--color-grey-1);
}

  stroke-width: 2;
  stroke-linecap: round;
}

/* The Workflow map. */

.workflow {
  grid-column: 1 / -1;
  grid-row: 4;
  margin-top: 112px;
}

.workflowTitle {
